// NEET UG Biology: Plant kingdom (NCERT Class 11, Chapter 3). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const nid = () => `pk-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];

// single-answer mcq; the right option is placed at a cycling position
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}


// ---------------------------------------------------------------- Level 1
mc(1, 'classification systems', 'A system of classification that used only a few vegetative or sexual characters, such as the stamens, is', 'artificial', ['natural', 'phylogenetic', 'numerical'], 'Artificial systems, such as that of Linnaeus, used a few easily seen characters, like the androecium. Natural systems use many characters, and phylogenetic systems use evolutionary relationships.');
mc(1, 'algae', 'Algae are mostly', 'aquatic, autotrophic and thalloid', ['terrestrial and heterotrophic', 'parasitic and non-green', 'vascular and seed bearing'], 'Algae are chlorophyll-bearing, simple, thalloid, autotrophic organisms, mostly aquatic (fresh water and marine).');
mc(1, 'algae', 'Green algae belong to the class', 'Chlorophyceae', ['Phaeophyceae', 'Rhodophyceae', 'Bacillariophyceae'], 'Chlorophyceae are green algae. Phaeophyceae are brown algae and Rhodophyceae are red algae.');
mc(1, 'algae', 'Agar is obtained from', 'red algae such as <i>Gelidium</i> and <i>Gracilaria</i>', ['green algae such as <i>Volvox</i>', 'brown algae such as <i>Fucus</i>', 'mosses such as <i>Funaria</i>'], 'Agar, used to grow microbes and in ice creams and jellies, comes from <i>Gelidium</i> and <i>Gracilaria</i>, which are red algae.');
mc(1, 'bryophytes', 'Bryophytes are called the amphibians of the plant kingdom because', 'they live on land but need water for fertilisation', ['they live only in water', 'they have vessels', 'they bear seeds'], 'They grow in damp places, but their male gametes are flagellated and swim in a film of water to reach the egg.');
mc(1, 'bryophytes', 'An example of a liverwort is', '<i>Marchantia</i>', ['<i>Funaria</i>', '<i>Sphagnum</i>', '<i>Pinus</i>'], '<i>Marchantia</i> is a thalloid liverwort. <i>Funaria</i>, <i>Polytrichum</i> and <i>Sphagnum</i> are mosses.');
mc(1, 'pteridophytes', 'The first terrestrial plants to have vascular tissues (xylem and phloem) are', 'pteridophytes', ['bryophytes', 'algae', 'fungi'], 'Pteridophytes (ferns and their allies) are the first land plants with xylem and phloem. Bryophytes have no vascular tissue.');
mc(1, 'pteridophytes', 'The gametophyte of a fern is a small heart-shaped structure called the', 'prothallus', ['protonema', 'strobilus', 'thallus of Marchantia'], 'The pteridophyte gametophyte is a small, free-living, multicellular, mostly photosynthetic prothallus. The protonema belongs to mosses.');
mc(1, 'gymnosperms', 'In gymnosperms the seeds are', 'naked, not enclosed in a fruit', ['inside a fruit', 'absent', 'enclosed in a gametophyte coat'], 'Gymnos means naked. The ovules are not enclosed by an ovary wall and the seeds are exposed.');
mc(1, 'gymnosperms', 'Which of these is a gymnosperm?', '<i>Cycas</i>', ['<i>Selaginella</i>', '<i>Marchantia</i>', '<i>Spirogyra</i>'], '<i>Cycas</i>, <i>Pinus</i> and <i>Cedrus</i> are gymnosperms. <i>Selaginella</i> is a pteridophyte and <i>Marchantia</i> a liverwort.');
mc(1, 'angiosperms', 'In angiosperms the seeds are enclosed in', 'fruits', ['cones', 'sporangia', 'prothalli'], 'Angiosperms bear flowers and seeds develop inside fruits, which form from the ovary.');
mc(1, 'angiosperms', 'The two classes of angiosperms are', 'dicotyledons and monocotyledons', ['homosporous and heterosporous', 'liverworts and mosses', 'cycads and conifers'], 'Angiosperms are divided into dicots, with two cotyledons, and monocots, with one.');
mc(1, 'life cycles', 'The alternation between a haploid and a diploid phase in the life cycle of a plant is called', 'alternation of generations', ['double fertilisation', 'heterospory', 'metagenesis of animals'], 'Plants have a gametophyte (haploid) and a sporophyte (diploid) phase that alternate.');
mc(1, 'algae', 'Which of these is a unicellular alga used as a protein-rich food supplement?', '<i>Chlorella</i>', ['<i>Laminaria</i>', '<i>Fucus</i>', '<i>Polysiphonia</i>'], '<i>Chlorella</i> and <i>Spirulina</i> are unicellular algae rich in protein and used as food supplements, even by space travellers.');

// ---------------------------------------------------------------- Level 2
mc(2, 'classification systems', 'Natural systems of classification, such as that of Bentham and Hooker, are based on', 'natural affinities, using many characters', ['only the number of stamens', 'only evolutionary history from fossils', 'only chemical composition'], 'Natural systems use external and internal features, such as anatomy and embryology. The number of stamens was used in artificial systems.');
mc(2, 'classification systems', 'Phylogenetic systems of classification are based on', 'evolutionary relationships and common ancestry', ['colour of flowers', 'habit of the plant only', 'use to man'], 'They assume that organisms in the same taxon have a common ancestor, so the classification shows evolutionary history.');
mc(2, 'classification systems', 'Chromosome number, structure and behaviour are used as clues in', 'cytotaxonomy', ['chemotaxonomy', 'numerical taxonomy', 'artificial taxonomy'], 'Cytotaxonomy uses cytological information. Chemotaxonomy uses chemical constituents of the plant.');
mc(2, 'classification systems', 'In numerical taxonomy', 'many characters are coded with numbers and processed by computers, giving each character equal importance', ['only one decisive character is used', 'only fossils are compared', 'only DNA is sequenced'], 'It considers all observable characters, assigns numbers and codes and processes the data with computers. Every character has equal weight.');
mc(2, 'algae', 'The reserve food in Chlorophyceae is', 'starch', ['laminarin and mannitol', 'floridean starch', 'glycogen'], 'Green algae store starch in pyrenoids (and sometimes as oil droplets). Brown algae store laminarin and mannitol, and red algae store floridean starch.');
mc(2, 'algae', 'Brown algae owe their colour to the pigment', 'fucoxanthin', ['phycoerythrin', 'chlorophyll b', 'carotene only'], 'Fucoxanthin (a xanthophyll) gives brown algae their colour. R-phycoerythrin is the red pigment of red algae.');
mc(2, 'algae', 'The red pigment of Rhodophyceae is', 'r-phycoerythrin', ['fucoxanthin', 'chlorophyll b', 'xanthophyll'], 'R-phycoerythrin gives the red colour. Red algae also have chlorophyll a and d.');
mc(2, 'algae', 'The plant body of a brown alga like <i>Laminaria</i> is attached to the substratum by', 'a holdfast', ['rhizoids with xylem', 'roots with root hairs', 'a rhizome'], 'Brown algae have a holdfast, a stalk called the stipe and a leaf-like frond. They have no true roots.');
mc(2, 'algae', 'Which alga is isogamous?', '<i>Spirogyra</i>', ['<i>Volvox</i>', '<i>Fucus</i>', '<i>Eudorina</i>'], '<i>Spirogyra</i> and <i>Ulothrix</i> are isogamous (gametes are similar in size). <i>Eudorina</i> is anisogamous and <i>Volvox</i> and <i>Fucus</i> are oogamous.');
mc(2, 'algae', 'Which of the following algae is oogamous?', '<i>Volvox</i>', ['<i>Ulothrix</i>', '<i>Spirogyra</i>', '<i>Eudorina</i>'], 'Oogamy has a large non-motile female gamete and a smaller motile male gamete, as in <i>Volvox</i> and <i>Fucus</i>.');
mc(2, 'algae', 'About what fraction of the total carbon dioxide fixation on Earth is done by algae through photosynthesis?', 'About half', ['About one tenth', 'About one fifth', 'Nearly all of it'], 'NCERT states that algae fix about half of the total CO<sub>2</sub> fixed on earth, and they increase the dissolved oxygen of their habitat.');
mc(2, 'bryophytes', 'The sex organ that makes biflagellate antherozoids in bryophytes is the', 'antheridium', ['archegonium', 'sporangium', 'gemma'], 'The antheridium produces biflagellate antherozoids. The archegonium is flask-shaped and has a single egg.');
mc(2, 'bryophytes', 'Gemmae are', 'green multicellular asexual buds in gemma cups', ['unicellular sexual cells', 'spores in a capsule', 'hairs on the sporophyte'], 'In liverworts such as <i>Marchantia</i> gemmae are formed in gemma cups on the thallus. They detach and grow into new thalli.');
mc(2, 'bryophytes', 'The sporophyte of a moss has', 'foot, seta and capsule', ['frond, stipe and holdfast', 'root, stem and leaf', 'prothallus and strobilus'], 'In bryophytes the sporophyte is differentiated into foot, seta and capsule. It depends on the gametophyte.');
mc(2, 'bryophytes', 'The creeping, green and often filamentous stage of the moss gametophyte formed directly from a spore is the', 'protonema', ['prothallus', 'gemma', 'seta'], 'The first stage of a moss gametophyte is the protonema; the second is the leafy stage that bears sex organs.');
mc(2, 'bryophytes', '<i>Sphagnum</i> is important because it gives', 'peat used as fuel and in packing', ['agar for culture media', 'timber', 'cycad flour'], '<i>Sphagnum</i> holds a lot of water, so its peat is used as fuel and as packing material for living plants.');
mc(2, 'pteridophytes', 'Leaf-like appendages that bear sporangia in pteridophytes are', 'sporophylls', ['fronds only', 'rhizoids', 'gemmae'], 'Sporophylls bear sporangia. In <i>Selaginella</i> and <i>Equisetum</i> they form compact strobili (cones).');
mc(2, 'pteridophytes', 'Small leaves as in <i>Selaginella</i> are called', 'microphylls', ['macrophylls', 'sporophylls only', 'fronds'], 'Selaginella has microphylls. Ferns have large leaves, macrophylls.');
mc(2, 'pteridophytes', 'Plants that produce two kinds of spores, large and small, are', 'heterosporous, as in <i>Selaginella</i> and <i>Salvinia</i>', ['homosporous, as in most ferns', 'isosporous, as in mosses', 'apomictic, as in <i>Pinus</i>'], 'Heterosporous plants make megaspores and microspores. Most pteridophytes are homosporous.');
mc(2, 'gymnosperms', 'Coralloid roots of <i>Cycas</i> are associated with', 'nitrogen-fixing cyanobacteria', ['mycorrhizal fungi', 'bacteria that cause nodules', 'algae that are red'], 'Cycas has small coralloid roots with N<sub>2</sub>-fixing cyanobacteria, and <i>Pinus</i> roots have mycorrhiza.');
mc(2, 'gymnosperms', 'One of the tallest tree species, belonging to the gymnosperms, is', '<i>Sequoia</i> (giant redwood)', ['<i>Eucalyptus</i>', '<i>Wolffia</i>', '<i>Ginkgo</i> only'], '<i>Sequoia</i>, the redwood, is a gymnosperm and one of the tallest. <i>Eucalyptus</i> is an angiosperm that is also very tall; <i>Wolffia</i> is the smallest angiosperm.');
mc(2, 'angiosperms', 'The smallest angiosperm is', '<i>Wolffia</i>', ['<i>Eucalyptus</i>', '<i>Sequoia</i>', '<i>Volvox</i>'], '<i>Wolffia</i> is a tiny aquatic flowering plant. <i>Eucalyptus</i> trees can exceed 100 m.');
mc(2, 'life cycles', 'In a haplontic life cycle the', 'dominant phase is a haploid gametophyte and the zygote undergoes meiosis', ['dominant phase is the diploid sporophyte', 'gametophyte is a few cells and dependent', 'zygote divides by mitosis to form a long diploid body'], 'In haplontic plants like <i>Volvox</i> and <i>Spirogyra</i> the free-living haploid body dominates and the sporophyte is only the zygote.');

// ---------------------------------------------------------------- Level 3
mc(3, 'classification systems', 'Which of the following combinations is correct?', 'Artificial system: few characters; natural system: many characters including internal features', ['Artificial system: many characters; natural system: one character', 'Phylogenetic system: based on number of stamens', 'Numerical taxonomy: one key character only'], 'Artificial systems use few (often vegetative) characters, natural ones use many, and phylogenetic ones follow evolutionary descent. Numerical taxonomy uses many characters with equal weight.');
mc(3, 'classification systems', 'Why did artificial systems fall out of use?', 'They gave equal weight to a few characters, so unrelated plants were grouped together and related plants were separated', ['They used too many characters', 'They were based on evolution', 'They needed computers'], 'Using vegetative characters or the androecium alone put distant organisms together and separated close relatives.');
mc(3, 'classification systems', 'Which taxonomic approach compares alkaloids and other plant chemicals for classification?', 'Chemotaxonomy', ['Cytotaxonomy', 'Numerical taxonomy', 'Artificial classification'], 'Chemotaxonomy uses chemical constituents; cytotaxonomy uses chromosomes.');
mc(3, 'algae', 'Pyrenoids are found in', 'Chlorophyceae and contain protein with starch', ['Rhodophyceae and contain floridean starch only', 'Phaeophyceae and contain mannitol only', 'bryophytes and contain gemmae'], 'Pyrenoids are located in the chloroplasts of green algae and have protein besides starch. They are for storage.');
mc(3, 'algae', 'The cell wall of Chlorophyceae is', 'cellulose in the inner layer and pectose in the outer layer', ['cellulose with a coat of algin', 'chitin', 'silica'], 'Green algae walls have two layers, an inner of cellulose and an outer of pectose. Brown algae have cellulose with algin.');
mc(3, 'algae', 'The cell wall of brown algae is', 'cellulose covered by a gelatinous coating of algin', ['pectose over cellulose', 'only chitin', 'only silica'], 'Brown algae have cellulosic walls covered with gelatinous algin. Algin is a hydrocolloid of commercial use.');
mc(3, 'algae', 'The pear-shaped zoospores with two unequal lateral flagella are found in', 'Phaeophyceae', ['Chlorophyceae', 'Rhodophyceae', 'bryophytes'], 'Brown algae have biflagellate pear-shaped zoospores with two unequal lateral flagella. Chlorophycean zoospores have 2 to 4 equal apical flagella.');
mc(3, 'algae', 'Flagellated stages are completely absent in the life cycle of', 'Rhodophyceae', ['Chlorophyceae', 'Phaeophyceae', 'bryophytes'], 'Red algae reproduce asexually by non-motile spores and sexually by non-motile gametes; there are no flagellated stages.');
mc(3, 'algae', 'The stored food of red algae, similar to amylopectin and glycogen, is', 'floridean starch', ['laminarin', 'mannitol', 'fat only'], 'Rhodophyceae store floridean starch. Phaeophyceae store laminarin and mannitol.');
mc(3, 'algae', 'Which of the following pairs is wrongly matched?', 'Rhodophyceae: fucoxanthin', ['Phaeophyceae: laminarin', 'Chlorophyceae: chlorophyll a and b', 'Rhodophyceae: floridean starch'], 'Fucoxanthin is the pigment of brown algae. Red algae have r-phycoerythrin.');
mc(3, 'algae', 'Which of these is a brown alga?', '<i>Sargassum</i>', ['<i>Polysiphonia</i>', '<i>Chara</i>', '<i>Porphyra</i>'], '<i>Sargassum</i>, <i>Laminaria</i>, <i>Fucus</i>, <i>Dictyota</i> and <i>Ectocarpus</i> are brown algae. <i>Polysiphonia</i> and <i>Porphyra</i> are red; <i>Chara</i> is green.');
mc(3, 'bryophytes', 'The sporophyte of bryophytes is', 'not free living, attached to and nourished by the gametophyte', ['free-living and dominant', 'absent', 'haploid and independent'], 'The zygote forms a multicellular sporophyte that stays on the photosynthetic gametophyte and gets nourishment from it.');
mc(3, 'bryophytes', 'Which of the following is TRUE for the main plant body of bryophytes?', 'It is haploid and a gametophyte, with rhizoids but no true roots', ['It is diploid and a sporophyte, with true roots', 'It is haploid, with xylem and phloem', 'It is diploid, with flowers'], 'The main body is the haploid gametophyte, attached by unicellular or multicellular rhizoids; there is no vascular tissue.');
mc(3, 'bryophytes', 'Which statement about the liverwort thallus is correct?', 'It is dorsiventral and closely appressed to the substrate', ['It is erect and radially symmetrical', 'It has a stipe and a frond', 'It has true roots and vessels'], 'A liverwort thallus is dorsiventral and flat on the ground. A stipe and a frond are in brown algae.');
mc(3, 'bryophytes', 'In mosses the spores germinate to produce', 'the protonema', ['a sporophyte', 'a prothallus with vascular tissue', 'a gemma cup'], 'A moss spore gives the creeping protonema, and the leafy stage grows from it as a lateral bud.');
mc(3, 'pteridophytes', 'In a fern, meiosis occurs in', 'spore mother cells of the sporangium', ['the zygote', 'the egg cell', 'the prothallus cells'], 'The sporophyte makes spores through meiosis in spore mother cells in sporangia. The spores are haploid and give prothalli.');
mc(3, 'pteridophytes', 'Why is the spread of living pteridophytes restricted to narrow geographical regions?', 'The gametophyte needs cool damp shady places and water for fertilisation', ['They need strong sunlight to make seeds', 'They need insects for pollination', 'They have no chlorophyll'], 'The prothallus needs cool damp shade, and the male gamete needs water to reach the archegonium.');
mc(3, 'pteridophytes', 'Which of these is a pteridophyte that forms strobili?', '<i>Equisetum</i>', ['<i>Adiantum</i>', '<i>Marchantia</i>', '<i>Funaria</i>'], '<i>Equisetum</i> and <i>Selaginella</i> bear strobili (cones). Ferns like <i>Adiantum</i> have sori on fronds instead.');
mc(3, 'pteridophytes', 'The development of the zygote into a young embryo within the female gametophyte retained on the sporophyte is a precursor of the', 'seed habit', ['alternation of generations', 'haplontic cycle', 'gemma formation'], 'In heterosporous pteridophytes the female gametophyte stays on the parent for a while. This is an important step in the evolution of seeds.');
mc(3, 'pteridophytes', 'Which pteridophyte class is correctly matched with its member?', 'Lycopsida: <i>Selaginella</i>', ['Pteropsida: <i>Equisetum</i>', 'Psilopsida: <i>Dryopteris</i>', 'Sphenopsida: <i>Adiantum</i>'], 'Psilopsida: <i>Psilotum</i>; Lycopsida: <i>Selaginella</i>, <i>Lycopodium</i>; Sphenopsida: <i>Equisetum</i>; Pteropsida: <i>Dryopteris</i>, <i>Pteris</i>, <i>Adiantum</i>.');
mc(3, 'gymnosperms', 'In <i>Pinus</i> the male and female cones are borne', 'on the same tree', ['on different trees', 'only on leaves', 'only on the root'], 'In <i>Pinus</i> both cones occur on one tree. In <i>Cycas</i> they are on different plants.');
mc(3, 'gymnosperms', 'Needle-like leaves, thick cuticle and sunken stomata in conifers help', 'to reduce water loss', ['to attract insects', 'to absorb nitrogen', 'to store starch'], 'These features reduce the surface area and transpiration, which suits extremes of temperature, humidity and wind.');
mc(3, 'gymnosperms', 'In gymnosperms the male gametophyte is', 'a highly reduced pollen grain', ['a prothallus', 'a free-living protonema', 'an embryo sac'], 'Pollen grains are highly reduced male gametophytes. The female gametophyte stays in the ovule.');
mc(3, 'gymnosperms', 'The pollen tube in gymnosperms carries male gametes to the', 'archegonia in the ovule', ['ovary wall', 'style', 'antheridium'], 'Gymnosperms have archegonia in the ovules, unlike angiosperms. The male gametes are discharged near the mouth of the archegonia.');
mc(3, 'angiosperms', 'The female gametophyte of angiosperms is', 'the embryo sac, typically 7-celled and 8-nucleate', ['the prothallus, 8-celled', 'the pollen grain, 3-celled', 'the protonema'], 'A typical embryo sac has an egg apparatus (egg and two synergids), three antipodals and a large central cell with two polar nuclei.');
mc(3, 'angiosperms', 'The primary endosperm nucleus in angiosperms is formed by fusion of', 'one male gamete with two polar nuclei', ['one male gamete with the egg', 'two male gametes with the egg', 'the synergids and antipodals'], 'Triple fusion forms a triploid primary endosperm nucleus. Syngamy with the egg forms the zygote.');
mc(3, 'angiosperms', 'Double fertilisation is the', 'syngamy plus triple fusion in the same embryo sac', ['fusion of two eggs', 'two pollen tubes fusing', 'fusion of two zygotes'], 'Two events occur: one male gamete fuses with the egg and the other with two polar nuclei.');
mc(3, 'life cycles', 'Which of these shows a haplontic life cycle?', '<i>Spirogyra</i>', ['<i>Fucus</i>', 'Fern', 'Moss'], '<i>Spirogyra</i> and <i>Volvox</i> are haplontic. <i>Fucus</i> is diplontic and ferns and mosses are haplo-diplontic.');
mc(3, 'life cycles', 'Which of these is a diplontic alga?', '<i>Fucus</i>', ['<i>Volvox</i>', '<i>Spirogyra</i>', '<i>Polysiphonia</i>'], 'In <i>Fucus</i> the diploid thallus is dominant and only the gametes are haploid. <i>Polysiphonia</i> is haplo-diplontic.');

// ---------------------------------------------------------------- Level 4
mc(4, 'life cycles', 'In bryophytes the dominant phase is', 'haploid gametophyte and the diploid sporophyte depends on it', ['diploid sporophyte and the haploid gametophyte depends on it', 'diploid sporophyte, independent', 'haploid gametophyte, which is dependent'], 'Bryophytes: gametophyte dominant and free living; sporophyte dependent. Pteridophytes: sporophyte dominant and free living; gametophyte independent but small.');
mc(4, 'life cycles', 'In a fern the spore mother cell has 48 chromosomes. How many chromosomes does a cell of the prothallus have?', '24', ['48', '12', '96'], 'The spore mother cell is diploid (2n = 48), so n = 24. Spores are n = 24 and divide by mitosis to the prothallus, so its cells have 24.');
mc(4, 'life cycles', 'The zygote of a moss has 20 chromosomes. How many chromosomes are in a cell of the protonema?', '10', ['20', '5', '40'], 'The zygote is 2n = 20, so n = 10. The protonema comes from a haploid spore, so its cells have 10.');
mc(4, 'life cycles', 'The cell of a leaf of <i>Pinus</i> has 24 chromosomes. How many chromosomes are expected in a pollen grain cell and in the endosperm (female gametophyte) cell of the same plant?', '12 and 12', ['24 and 12', '12 and 24', '12 and 36'], 'The leaf is the diploid sporophyte, 2n = 24, so n = 12. Pollen grains are male gametophyte (n) and the gymnosperm endosperm is the haploid female gametophyte (n), so both are 12.', 'Gymnosperm endosperm is haploid, not triploid.');
mc(4, 'life cycles', 'A flowering plant has 2n = 14. How many chromosomes are present in the egg cell, the zygote and the endosperm cell respectively?', '7, 14 and 21', ['14, 14 and 28', '7, 14 and 14', '7, 7 and 21'], 'The egg is haploid, n = 7. The zygote is diploid, 14. The endosperm is triploid (n + n + n) = 21.');
mc(4, 'life cycles', 'Which life cycle shows both the haploid and diploid phases as multicellular, free-living bodies?', 'Pteridophytes', ['<i>Volvox</i>', '<i>Fucus</i>', 'Angiosperms'], 'In ferns both the sporophyte and the prothallus are independent. In bryophytes the sporophyte is dependent, in angiosperms the gametophyte is dependent.', 'Bryophytes are haplo-diplontic but the sporophyte is not free-living.');
mc(4, 'life cycles', 'In which of the following is the life cycle haplo-diplontic?', '<i>Ectocarpus</i>, <i>Polysiphonia</i> and kelps', ['<i>Volvox</i>, <i>Spirogyra</i> and <i>Chlamydomonas</i>', '<i>Fucus</i>, <i>Cycas</i> and <i>Pinus</i>', '<i>Spirogyra</i>, <i>Fucus</i> and moss'], 'NCERT names <i>Ectocarpus</i>, <i>Polysiphonia</i> and kelps (as well as bryophytes and pteridophytes) as haplo-diplontic. Others are haplontic or diplontic.');
mc(4, 'life cycles', 'Zygotic meiosis is seen in', 'haplontic forms such as <i>Spirogyra</i>', ['diplontic forms such as <i>Fucus</i>', 'angiosperms', 'ferns'], 'In haplontic cycles the zygote divides by meiosis to give haploid spores or cells. In diplontic organisms meiosis makes gametes.');
mc(4, 'algae', 'Which statement about the sexual reproduction of algae is correct?', 'Isogamous gametes are alike in size, anisogamous are different in size, and oogamous have a large static egg and a small motile male gamete', ['Isogamous gametes are alike and always non-flagellated', 'Oogamous gametes are alike in size', 'Anisogamous gametes are static'], 'Isogamous gametes may be flagellated or non-flagellated but are similar in size. In oogamy the female gamete is large and non-motile.');
mc(4, 'algae', 'Which of the following algal products is correctly matched?', 'Algin: brown algae', ['Agar: brown algae', 'Carrageen: green algae', 'Floridean starch: brown algae'], 'Algin is from brown algae. Agar (<i>Gelidium</i>, <i>Gracilaria</i>) and carrageen come from red algae.');
mc(4, 'algae', 'Which of the following pairs of examples and the algal class is correct?', '<i>Chara</i> and <i>Ulothrix</i>: Chlorophyceae', ['<i>Chara</i> and <i>Ulothrix</i>: Phaeophyceae', '<i>Dictyota</i> and <i>Porphyra</i>: Phaeophyceae', '<i>Gracilaria</i> and <i>Fucus</i>: Rhodophyceae'], '<i>Chara</i> and <i>Ulothrix</i> are green algae. <i>Dictyota</i> is brown, <i>Porphyra</i> is red, <i>Gracilaria</i> is red and <i>Fucus</i> is brown.');
mc(4, 'algae', 'Red algae can grow at greater depths than most other algae because they contain', 'r-phycoerythrin, which absorbs the blue-green light that reaches deeper', ['fucoxanthin, which absorbs red light', 'chlorophyll b, which absorbs green light', 'more chitin in the wall'], 'Red algae thrive at depths where little light penetrates, as r-phycoerythrin absorbs the light that goes deepest; red light is absorbed near the surface.', 'Different pigments of different algae suit different depths.');
mc(4, 'bryophytes', 'How many of the following are bryophytes: <i>Funaria</i>, <i>Marchantia</i>, <i>Selaginella</i>, <i>Sphagnum</i>, <i>Polytrichum</i>?', 'Four', ['Three', 'Five', 'Two'], '<i>Funaria</i>, <i>Marchantia</i>, <i>Sphagnum</i> and <i>Polytrichum</i> are bryophytes. <i>Selaginella</i> is a pteridophyte.', undefined, 'statements');
mc(4, 'bryophytes', 'In liverworts, which structure helps in asexual reproduction and which in the dispersal of the sporophyte\'s spores respectively?', 'Gemmae; capsule', ['Capsule; gemmae', 'Protonema; seta', 'Foot; gemmae'], 'Gemmae in gemma cups are the asexual buds, while spores are made in the capsule after meiosis.');
mc(4, 'pteridophytes', 'Which of the following statements about pteridophytes is wrong?', 'The dominant plant is the gametophyte', ['The main body is a sporophyte with root, stem and leaves', 'The gametophyte is a prothallus', 'Water is needed for fertilisation'], 'In pteridophytes the main plant body is the diploid sporophyte, which has true root, stem and leaves.');
mc(4, 'pteridophytes', 'Which is a true statement about homospory and heterospory?', 'Heterosporous plants produce megaspores that give female gametophytes and microspores that give male gametophytes', ['Homosporous plants have male and female prothalli of separate spore types', 'Heterospory is found in <i>Dryopteris</i>', 'Heterospory is found in mosses'], 'In heterospory, megaspores and microspores are of two types and give female and male gametophytes. Most ferns, like <i>Dryopteris</i>, are homosporous.');
mc(4, 'gymnosperms', 'Which statement about the gymnosperm life cycle is correct?', 'They are heterosporous and the gametophytes develop within the sporangia retained on the sporophyte', ['They are homosporous and free-living gametophytes occur', 'They produce seeds inside fruits', 'They have vessels and companion cells'], 'Gymnosperms are heterosporous. The male and female gametophytes are very reduced and retained, and the ovules become naked seeds. Companion cells and vessels are angiosperm features.');
mc(4, 'gymnosperms', 'In <i>Cycas</i> the stem is', 'unbranched and the leaves pinnate', ['branched and the leaves needle-like', 'absent', 'a rhizome with fronds'], '<i>Cycas</i> has an unbranched stem and pinnate leaves, while <i>Pinus</i> and <i>Cedrus</i> have branched stems.');
mc(4, 'angiosperms', 'Which of the following parts of an embryo sac fuses with a male gamete to give the endosperm?', 'The central cell with two polar nuclei', ['The synergids', 'The antipodal cells', 'The egg apparatus'], 'The male gamete fuses with the two polar nuclei of the central cell. Synergids and antipodals do not take part.');
mc(4, 'angiosperms', 'Which statement is correct for the angiosperm gametophytes?', 'They are highly reduced, with the pollen grain as male gametophyte and the embryo sac as female', ['They are free-living and photosynthetic', 'They are prothalli', 'They are multicellular filaments'], 'Both gametophytes are tiny and live on the dominant sporophyte.');

asr(1, 'bryophytes', 'Bryophytes need water for fertilisation.', 'Their antherozoids are flagellated and swim to the egg.', 0, 'Motile flagellated male gametes can reach the archegonium only through water, so R explains A.');
asr(2, 'algae', 'Algae are important primary producers in water.', 'Algae have chlorophyll and do photosynthesis.', 0, 'Photosynthetic algae make food and oxygen, forming the base of aquatic food chains. R explains A.');
asr(2, 'pteridophytes', 'Pteridophytes are the first land plants with vascular tissue.', 'They have xylem and phloem.', 0, 'Xylem and phloem allow transport of water and food in land plants. Both are true and R explains A.');
asr(3, 'gymnosperms', 'Gymnosperms are called naked-seeded plants.', 'Their ovules are not enclosed by an ovary wall.', 0, 'Because no ovary wall encloses the ovule, the seed that develops from it is uncovered.');
asr(3, 'algae', 'Red algae have no flagellated stages.', 'Red algae reproduce sexually by oogamy.', 1, 'A is true, since spores and gametes are non-motile. R is also true, as the sexual reproduction is oogamous, but oogamy alone does not explain the absence of flagella (brown algae are also oogamous in some forms and have flagellated gametes), so R is not the explanation.');
asr(3, 'bryophytes', 'The sporophyte of a moss is not independent.', 'The sporophyte is attached to the gametophyte and takes its nourishment from it.', 0, 'Dependence on the photosynthetic gametophyte for food is exactly why the sporophyte is not independent. R explains A.');
asr(4, 'life cycles', 'Haplontic plants have no diploid multicellular body.', 'In haplontic plants the zygote undergoes meiosis.', 0, 'Zygotic meiosis means the diploid phase is only the one-celled zygote, so there is no diploid multicellular body.');
asr(4, 'angiosperms', 'Endosperm of angiosperms is triploid.', 'It is formed by the fusion of one male gamete with two polar nuclei.', 0, 'Two haploid polar nuclei plus one haploid male gamete give 3n. R explains A.');
asr(4, 'pteridophytes', 'The spread of pteridophytes is restricted to narrow regions.', 'Sporophytes of pteridophytes need strong sunlight.', 2, 'A is true because the gametophytes need cool, damp and shady places. R is false because the restriction comes from the needs of the gametophyte; sporophyte light need is not the reason.');
asr(5, 'algae', 'Chlorella and Spirulina are used as food supplements.', 'Both are unicellular algae rich in protein.', 0, 'They are protein-rich single-celled algae and have been used even by space travellers.');
asr(5, 'gymnosperms', 'The gymnosperm endosperm is haploid.', 'It is the female gametophyte tissue.', 0, 'In gymnosperms the food tissue is the female gametophyte, so it is n. This differs from the triploid endosperm of angiosperms.');

stm(1, 'algae', 'Brown algae are mostly marine.', 'Red algae are only found in fresh water.', 2, 'Most brown algae are marine. Red algae are mostly marine too, so II is wrong.');
stm(2, 'bryophytes', 'Mosses are bryophytes.', 'Mosses have true roots, stems and leaves.', 2, 'Mosses are bryophytes. They lack true roots, stems and leaves, so II is wrong.');
stm(2, 'life cycles', 'In diplontic life cycle the plant body is diploid.', 'Gymnosperms and angiosperms are diplontic.', 0, 'The dominant free-living body is a diploid sporophyte in seed plants, whose gametophytes are tiny. Both are right.');
stm(3, 'pteridophytes', 'In <i>Selaginella</i> the sporophylls form strobili.', 'In <i>Selaginella</i> the leaves are macrophylls.', 2, '<i>Selaginella</i> has cones, so I is right. Its leaves are small microphylls, so II is wrong.');
stm(3, 'algae', 'Laminarin and mannitol are reserve foods of brown algae.', 'Floridean starch is the reserve food of green algae.', 2, 'I is right. Floridean starch is of red algae; green algae store starch.');
stm(3, 'gymnosperms', 'Pinus roots have mycorrhiza.', 'Cycas has coralloid roots with fungi.', 2, '<i>Pinus</i> has mycorrhiza (I right). <i>Cycas</i> coralloid roots hold nitrogen-fixing cyanobacteria, not fungi (II wrong).');
stm(3, 'angiosperms', 'The embryo sac typically has 8 nuclei.', 'The egg apparatus contains the egg and two synergids.', 0, 'The embryo sac has 3 + 3 + 2 nuclei (egg apparatus 3, antipodals 3 and 2 polar nuclei) = 8. Both statements are correct.');
stm(4, 'life cycles', 'In a haplo-diplontic cycle the haploid and diploid phases are both multicellular.', 'Bryophytes are haplo-diplontic with a dominant diploid phase.', 2, 'I is right. In bryophytes the haploid gametophyte is dominant, so II is wrong.');
stm(4, 'bryophytes', 'The antheridium of bryophytes produces biflagellate antherozoids.', 'The archegonium is flask-shaped and produces many eggs.', 2, 'I is right. The archegonium produces a single egg, so II is wrong.');
stm(4, 'algae', 'Chlorophyceae can be unicellular, colonial or filamentous.', 'Fucoxanthin is the main accessory pigment in them.', 2, 'I is right (<i>Chlamydomonas</i>, <i>Volvox</i>, <i>Ulothrix</i>). Fucoxanthin is in Phaeophyceae, so II is wrong.');
stm(5, 'classification systems', 'Numerical taxonomy gives equal importance to every character.', 'It can use hundreds of characters with the help of computers.', 0, 'Both are true: characters are coded and weighed equally, and computers handle large amounts of data.');
stm(5, 'pteridophytes', 'In heterosporous pteridophytes the female gametophyte may be retained on the parent sporophyte.', 'This is a precursor of the seed habit.', 0, 'Retention of the megaspore and female gametophyte, with the zygote developing in it, foreshadows the seed. Both are right.');

mc(4, 'mixed statements', 'How many of the following are correct? (i) Chlorophyceae have flagellated zoospores. (ii) Phaeophyceae have a holdfast, stipe and frond. (iii) Rhodophyceae have flagella in the gametes. (iv) Phaeophyceae store floridean starch.', 'Two', ['One', 'Three', 'Four'], '(i) and (ii) are correct. (iii) is wrong because red algae have no flagellated stages, and (iv) is wrong because floridean starch is in red algae.', undefined, 'statements');
mc(5, 'mixed statements', 'How many of the following plants have a dominant diploid sporophyte? Moss, <i>Selaginella</i>, <i>Pinus</i>, <i>Spirogyra</i>, <i>Fucus</i>, <i>Marchantia</i>', 'Three', ['Two', 'Four', 'Five'], '<i>Selaginella</i> (pteridophyte), <i>Pinus</i> (gymnosperm) and <i>Fucus</i> (diplontic alga) have dominant diploid bodies. Moss and <i>Marchantia</i> are bryophytes with dominant gametophytes, and <i>Spirogyra</i> is haplontic.', 'Fucus is an alga but a diplontic one.', 'statements');
mc(5, 'mixed statements', 'Which of these correctly orders the plant groups by increasing reduction of the gametophyte?', 'Bryophytes, pteridophytes, gymnosperms, angiosperms', ['Angiosperms, gymnosperms, pteridophytes, bryophytes', 'Pteridophytes, bryophytes, angiosperms, gymnosperms', 'Gymnosperms, bryophytes, pteridophytes, angiosperms'], 'The gametophyte is a large dominant body in bryophytes, a small free prothallus in pteridophytes, a retained few-celled body in gymnosperms and the most reduced (pollen, embryo sac) in angiosperms.');
mc(5, 'mixed statements', 'A plant has a free-living, photosynthetic, thalloid haploid body that bears flask-shaped female organs, and a spore-bearing diploid phase that cannot live alone. It is', 'a bryophyte such as <i>Marchantia</i>', ['a pteridophyte such as <i>Pteris</i>', 'a gymnosperm such as <i>Cycas</i>', 'a brown alga such as <i>Fucus</i>'], 'Dominant haploid thallus, archegonia (flask-shaped) and a dependent sporophyte are bryophyte features. A fern sporophyte is independent.');
mc(5, 'mixed statements', 'Which of the following is NOT a similarity between gymnosperms and angiosperms?', 'Seeds enclosed in fruits', ['Dominant sporophyte', 'Heterospory', 'Highly reduced gametophytes'], 'Both are heterosporous seed plants with a dominant sporophyte and reduced gametophytes. Only angiosperms have fruits.');
mc(5, 'mixed statements', 'Pollen tube delivering male gametes to an archegonium inside an ovule indicates a', 'gymnosperm', ['moss', 'angiosperm', 'red alga'], 'Archegonia in ovules occur in gymnosperms. Angiosperms have no archegonium and the male gametes go to the embryo sac. Mosses lack ovules.');
mc(5, 'mixed statements', 'Which comparison of algae groups is correct?', 'Chlorophyceae have equal apical flagella, while Phaeophyceae have two unequal lateral flagella', ['Chlorophyceae have unequal lateral flagella, Phaeophyceae have equal apical flagella', 'Both have only one flagellum', 'Rhodophyceae have unequal lateral flagella'], 'Chlorophycean zoospores have 2 to 4 equal flagella at the apex; phaeophycean zoospores have two unequal flagella attached to the side. Red algae have none.');
mc(5, 'mixed statements', 'Total number of nuclei in a mature typical angiosperm embryo sac, and the number of them that become the endosperm after fertilisation (counting both polar nuclei and the male gamete nucleus), are respectively', '8 and 3', ['7 and 3', '8 and 2', '7 and 2'], 'The embryo sac has 8 nuclei (egg, 2 synergids, 3 antipodals, 2 polar nuclei). The endosperm nucleus forms from 2 polar nuclei and 1 male nucleus, 3 in all.', 'Do not mix the 7 cells with the 8 nuclei.');
mc(5, 'angiosperms', 'In an angiosperm with 2n = 16, how many chromosomes does the primary endosperm nucleus carry, and how many does each antipodal cell carry?', '24 and 8', ['16 and 8', '24 and 16', '8 and 24'], 'The PEN is triploid, 3n = 24. Antipodals are part of the haploid embryo sac, n = 8.');
mc(5, 'algae', 'In a diplontic alga with 2n = 20, a gamete has', '10 chromosomes, formed by meiosis in the gamete-forming cells', ['20 chromosomes, formed by mitosis', '40 chromosomes, formed by fusion', '5 chromosomes'], 'In diplontic life cycles the body is 2n and meiosis produces haploid gametes (n = 10). Mitosis would keep 20.');

match(2, 'algae', 'pm1', 'Algal class and pigment or reserve', ['A. Chlorophyceae', 'B. Phaeophyceae', 'C. Rhodophyceae', 'D. Chlorophyceae (reserve)'], ['p. Fucoxanthin', 'q. Starch', 'r. r-Phycoerythrin', 's. Chlorophyll a and b'], 'A-s, B-p, C-r, D-q', ['A-p, B-s, C-r, D-q', 'A-s, B-r, C-p, D-q', 'A-q, B-p, C-r, D-s'], 'Green algae have chlorophylls a and b and store starch. Brown algae have fucoxanthin and red algae r-phycoerythrin.');
match(3, 'plant groups', 'pm2', 'Plant and group', ['A. <i>Marchantia</i>', 'B. <i>Selaginella</i>', 'C. <i>Cycas</i>', 'D. <i>Sphagnum</i>'], ['p. Gymnosperm', 'q. Liverwort', 'r. Pteridophyte', 's. Moss'], 'A-q, B-r, C-p, D-s', ['A-s, B-r, C-p, D-q', 'A-q, B-p, C-r, D-s', 'A-r, B-q, C-p, D-s'], '<i>Marchantia</i> is a liverwort, <i>Selaginella</i> a pteridophyte, <i>Cycas</i> a gymnosperm and <i>Sphagnum</i> a moss.');
match(3, 'life cycles', 'pm3', 'Plant and life cycle', ['A. <i>Volvox</i>', 'B. <i>Fucus</i>', 'C. Fern', 'D. <i>Pinus</i>'], ['p. Haplontic', 'q. Haplo-diplontic', 'r. Diplontic (alga)', 's. Diplontic (seed plant)'], 'A-p, B-r, C-q, D-s', ['A-r, B-p, C-q, D-s', 'A-p, B-r, C-s, D-q', 'A-q, B-r, C-p, D-s'], '<i>Volvox</i> is haplontic, <i>Fucus</i> diplontic, ferns haplo-diplontic and <i>Pinus</i> diplontic.');
match(4, 'taxonomy', 'pm4', 'Approach and basis', ['A. Cytotaxonomy', 'B. Chemotaxonomy', 'C. Numerical taxonomy', 'D. Phylogenetic'], ['p. Chromosome number and behaviour', 'q. Chemical constituents', 'r. Coded characters processed by computers', 's. Evolutionary relationships'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Each approach uses its own source of information.');
match(4, 'pteridophytes', 'pm5', 'Class and example', ['A. Psilopsida', 'B. Lycopsida', 'C. Sphenopsida', 'D. Pteropsida'], ['p. <i>Equisetum</i>', 'q. <i>Psilotum</i>', 'r. <i>Adiantum</i>', 's. <i>Lycopodium</i>'], 'A-q, B-s, C-p, D-r', ['A-s, B-q, C-p, D-r', 'A-q, B-s, C-r, D-p', 'A-p, B-s, C-q, D-r'], 'Psilopsida: <i>Psilotum</i>; Lycopsida: <i>Selaginella</i> and <i>Lycopodium</i>; Sphenopsida: <i>Equisetum</i>; Pteropsida: <i>Dryopteris</i>, <i>Pteris</i>, <i>Adiantum</i>.');
match(5, 'algae', 'pm6', 'Algal gamete type and example', ['A. Isogamous', 'B. Anisogamous', 'C. Oogamous (colonial)', 'D. Oogamous (brown alga)'], ['p. <i>Eudorina</i>', 'q. <i>Volvox</i>', 'r. <i>Fucus</i>', 's. <i>Spirogyra</i>'], 'A-s, B-p, C-q, D-r', ['A-p, B-s, C-q, D-r', 'A-s, B-p, C-r, D-q', 'A-s, B-q, C-p, D-r'], '<i>Spirogyra</i> is isogamous, <i>Eudorina</i> anisogamous, <i>Volvox</i> oogamous and <i>Fucus</i> oogamous.');

pass('p1', 'Passage: a plant collection', 'A student collects three plants. Plant P is a flat green thallus lying on moist soil with cup-shaped structures holding small green buds, and rhizoids below. Plant Q is a plant with true roots, a creeping stem and small scale-like leaves, and cone-like structures at the shoot tips with two sizes of spores. Plant R is a tall tree with needle-like leaves; its seeds are borne on cone scales and are not covered by a fruit.');
pq('p1', 3, 'bryophytes', 'The cup-shaped structures of plant P are', 'gemma cups holding asexual buds', ['antheridia holding sperms', 'sori holding spores', 'archegonia holding eggs'], 'A flat thallus with gemma cups is a liverwort like <i>Marchantia</i>. Gemmae are asexual buds.');
pq('p1', 4, 'pteridophytes', 'Plant Q is likely', '<i>Selaginella</i>, a heterosporous pteridophyte with strobili', ['<i>Marchantia</i>, a bryophyte', '<i>Pinus</i>, a gymnosperm', '<i>Funaria</i>, a moss'], 'True roots, small leaves (microphylls), cones and two kinds of spores (macro and micro) show heterosporous <i>Selaginella</i>.');
pq('p1', 4, 'gymnosperms', 'The life cycle of plant R is', 'diplontic, with a very reduced male gametophyte as pollen grain', ['haplontic with a free-living gametophyte', 'haplo-diplontic with a dominant gametophyte', 'haplontic with zygotic meiosis'], 'A seed-bearing conifer such as <i>Pinus</i> has a dominant sporophyte and reduced gametophytes retained on it.');
pass('p2', 'Passage: chromosome counting', 'Consider a flowering plant in which a cell of the root tip has 18 chromosomes. A pollen mother cell undergoes meiosis to form pollen grains, and the embryo sac forms from a megaspore. After double fertilisation a seed develops.');
pq('p2', 3, 'angiosperms', 'The number of chromosomes in the egg cell of this plant is', '9', ['18', '27', '36'], 'The root tip cell is diploid, 2n = 18. The egg is haploid, n = 9.');
pq('p2', 4, 'angiosperms', 'The number of chromosomes in a cell of the endosperm and in the zygote are respectively', '27 and 18', ['18 and 27', '27 and 9', '9 and 18'], 'Endosperm is triploid (n + n + n = 27), the zygote is 2n = 18.');
pq('p2', 5, 'angiosperms', 'The number of chromosomes in a cell of the seed coat (from integuments of the ovule) is', '18', ['9', '27', '36'], 'The seed coat develops from the integuments of the ovule, which are tissues of the sporophyte (2n = 18) and not from fertilisation products.', 'Seed coat is maternal sporophyte tissue, not endosperm.');

// ---------------------------------------------------------------- Expansion (added 2026-11-22)
// ---- Level 2
mc(2, 'classification systems', 'Artificial systems of classification, such as that of Linnaeus, relied on', 'a few vegetative and sexual characters, such as the androecium structure', ['evolutionary relationships', 'chromosome numbers only', 'chemical constituents only'], 'These systems gave equal weight to a few characters and separated closely related species.');
mc(2, 'classification systems', 'The study of the chemical constituents of plants as an aid to classification is called', 'chemotaxonomy', ['cytotaxonomy', 'numerical taxonomy', 'phylogeny'], 'Chemotaxonomy uses chemicals such as alkaloids.');
mc(2, 'algae', 'The photosynthetic pigments of green algae are', 'chlorophyll a and b', ['chlorophyll a and c', 'chlorophyll a and d', 'phycoerythrin only'], 'They are green because chlorophyll a and b dominate.');
mc(2, 'algae', 'Which of the following is a filamentous green alga?', 'Spirogyra', ['Volvox', 'Chlamydomonas', 'Laminaria'], 'Spirogyra and Ulothrix are filamentous; Volvox is colonial; Chlamydomonas is unicellular.');
mc(2, 'algae', 'Which pigment gives brown algae their colour?', 'Fucoxanthin', ['Phycoerythrin', 'Chlorophyll b', 'Carotene only'], 'Fucoxanthin gives the olive green to brown colour.');
mc(2, 'algae', 'Gelidium and Gracilaria give', 'agar', ['algin', 'laminarin', 'peat'], 'Agar is used to grow microbes and in jellies and ice creams.');
mc(2, 'algae', 'Which algal product is a hydrocolloid from brown algae?', 'Algin', ['Agar', 'Peat', 'Chitin'], 'Brown algae yield algin and red algae yield carrageen and agar.');
mc(2, 'bryophytes', 'Rhizoids of bryophytes are', 'root-like structures that anchor the plant', ['true roots with xylem', 'sex organs', 'spore sacs'], 'Bryophytes lack true roots, stems or leaves.');
mc(2, 'bryophytes', 'A moss capsule contains', 'spores', ['gemmae', 'eggs', 'antherozoids'], 'The sporophyte consists of foot, seta and capsule.');
mc(2, 'pteridophytes', 'Which of these is a fern?', 'Dryopteris', ['Equisetum', 'Selaginella', 'Funaria'], 'Dryopteris, Pteris and Adiantum are ferns (Pteropsida).');
mc(2, 'pteridophytes', 'Equisetum belongs to', 'the horsetails (Sphenopsida)', ['ferns (Pteropsida)', 'club mosses (Lycopsida)', 'Psilopsida'], 'Equisetum is the horsetail.');
mc(2, 'gymnosperms', 'Which gymnosperm has needle-like leaves?', 'Pinus', ['Cycas', 'Ginkgo', 'Sargassum'], 'Conifers such as Pinus have needles. Cycas has pinnate leaves.');
mc(2, 'angiosperms', 'The male gametophyte of an angiosperm is the', 'pollen grain', ['embryo sac', 'ovule', 'stamen'], 'Pollen grains develop from microspores in anthers.');
mc(2, 'angiosperms', 'The ovule of an angiosperm develops into a', 'seed', ['fruit', 'flower', 'gametophyte'], 'The ovary becomes the fruit.');

// ---- Level 3
mc(3, 'classification systems', 'Which system arranges plants on the basis of their evolutionary relationships?', 'Phylogenetic system', ['Artificial system', 'Natural system of Bentham and Hooker', 'Numerical system'], 'The phylogenetic system uses the idea of common ancestry. The natural system uses natural affinities.', 'Natural and phylogenetic are different.');
mc(3, 'classification systems', 'Numerical taxonomy uses', 'numbers and codes assigned to all characters with computer processing', ['chromosome shape only', 'chemical test only', 'a few floral characters'], 'Every character is given equal weight.');
mc(3, 'classification systems', 'Cytotaxonomy uses', 'cytological information such as chromosome number and behaviour', ['plant extracts', 'computer codes', 'floral colour'], 'It is a basis of classification.');
mc(3, 'algae', 'The cell wall of green algae is made of', 'an inner layer of cellulose and an outer layer of pectose', ['cellulose and algin', 'chitin', 'peptidoglycan'], 'NCERT description.');
mc(3, 'algae', 'The plant body of Fucus or Laminaria shows', 'holdfast, stipe and frond', ['rhizoids, stem and leaf', 'thallus only', 'protonema'], 'Brown algae often have this three-part organisation.');
mc(3, 'algae', 'Floridean starch is the reserve food of', 'red algae', ['green algae', 'brown algae', 'mosses'], 'It resembles amylopectin and glycogen.');
mc(3, 'algae', 'The sexual reproduction of Volvox is', 'oogamous', ['isogamous', 'anisogamous', 'absent'], 'Volvox, Fucus and Chara are examples of oogamy.');
mc(3, 'algae', 'The sexual reproduction in Spirogyra is', 'isogamous', ['oogamous', 'anisogamous', 'asexual only'], 'Similar gametes fuse.');
mc(3, 'algae', 'Which alga is anisogamous?', 'Eudorina', ['Spirogyra', 'Volvox', 'Ulothrix'], 'Eudorina shows anisogamy.');
mc(3, 'algae', 'The asexual spores of algae that are flagellated are called', 'zoospores', ['aplanospores', 'conidia', 'sporangiospores'], 'Zoospores are motile.');
mc(3, 'algae', 'Which of these red algae is used as food?', 'Porphyra', ['Fucus', 'Ectocarpus', 'Spirogyra'], 'Porphyra, Laminaria and Sargassum are used as food.', 'Laminaria and Sargassum are brown algae.');
mc(3, 'algae', 'Chlorella is useful because', 'it is a protein-rich single-cell protein used by space travellers', ['it makes agar', 'it makes algin', 'it makes peat'], 'Chlorella and Spirulina are used as food supplements.');
mc(3, 'bryophytes', 'The antheridium of a bryophyte releases', 'biflagellate antherozoids', ['uniflagellate zoospores', 'non-motile gametes', 'pollen grains'], 'They swim in water to the archegonium.');
mc(3, 'bryophytes', 'The archegonium of a bryophyte is', 'flask-shaped with a single egg', ['spherical with many eggs', 'a sac of spores', 'club-shaped with sperm'], 'It has a neck and a venter.');
mc(3, 'bryophytes', 'Gemma cups are found in', 'Marchantia', ['Funaria', 'Sphagnum', 'Polytrichum'], 'Gemmae are green multicellular asexual buds.');
mc(3, 'bryophytes', 'In a moss, the protonema develops from', 'a spore', ['a zygote', 'a gemma only', 'a seta'], 'The spore germinates into the protonema.');
mc(3, 'bryophytes', 'Mosses along with lichens', 'colonise rocks and make them suitable for higher plants', ['form peat', 'form coal', 'form timber'], 'They are pioneers on bare rocks.');
mc(3, 'pteridophytes', 'The prothallus of a fern is', 'a free-living, photosynthetic haploid gametophyte', ['a diploid sporophyte', 'a parasite on the sporophyte', 'a spore'], 'It needs cool damp shady places.');
mc(3, 'pteridophytes', 'Sporophylls forming compact structures are called', 'strobili', ['sori only', 'gemmae', 'protonema'], 'Equisetum and Selaginella have strobili.');
mc(3, 'pteridophytes', 'Heterosporous pteridophytes include', 'Selaginella and Salvinia', ['Dryopteris and Pteris', 'Equisetum and Adiantum', 'Marchantia and Funaria'], 'They produce macrospores and microspores.');
mc(3, 'pteridophytes', 'The seed habit evolved from the heterosporous pteridophytes because', 'the zygote develops into an embryo inside the female gametophyte retained on the sporophyte', ['spores are lost', 'sexual reproduction is lost', 'zoospores form'], 'It is a precursor of the seed habit.');
mc(3, 'gymnosperms', 'Coralloid roots of Cycas are associated with', 'nitrogen-fixing cyanobacteria', ['mycorrhiza', 'Rhizobium', 'algae of lichens'], 'Pinus has mycorrhiza.');
mc(3, 'gymnosperms', 'The male cones of Pinus bear', 'microsporophylls with microsporangia', ['megasporophylls', 'ovules', 'strobili with seeds'], 'Pollen grains develop in microsporangia.');
mc(3, 'gymnosperms', 'The megaspore mother cell in gymnosperms is differentiated from', 'the nucellus', ['the integument', 'the pollen grain', 'the micropyle'], 'It lies within the megasporangium (nucellus).');
mc(3, 'gymnosperms', 'Seeds in gymnosperms are', 'not covered by fruit wall', ['enclosed in an ovary', 'absent', 'enclosed in a pericarp'], 'Ovules are not enclosed in an ovary wall.');
mc(3, 'gymnosperms', 'Which of these is a gymnosperm tree among the tallest tree species?', 'Sequoia', ['Eucalyptus', 'Wolffia', 'Mangifera'], 'Sequoia (redwood) is a gymnosperm; Eucalyptus is an angiosperm.');
mc(3, 'angiosperms', 'The egg apparatus of an embryo sac consists of', 'one egg cell and two synergids', ['egg and antipodals', 'three synergids', 'polar nuclei and egg'], 'The egg apparatus is at the micropylar end.');
mc(3, 'angiosperms', 'The cells present at the chalazal end of the embryo sac are', 'antipodals', ['synergids', 'polar nuclei', 'egg cells'], 'Three antipodals are there at the chalazal end.');
mc(3, 'angiosperms', 'The central cell of the embryo sac has', 'two polar nuclei', ['one egg', 'three antipodals', 'two synergids'], 'Fusion of male gamete with the two polar nuclei gives PEN.');
mc(3, 'angiosperms', 'The smallest angiosperm is', 'Wolffia', ['Sequoia', 'Eucalyptus', 'Cycas'], 'Wolffia is a tiny floating plant.');
mc(3, 'life cycles', 'The dominant phase in the life cycle of pteridophytes is', 'the sporophyte', ['the gametophyte', 'the protonema', 'the zygote'], 'The sporophyte is independent.');
mc(3, 'life cycles', 'Which of the following is haplo-diplontic?', 'Ectocarpus', ['Volvox', 'Fucus', 'Pinus'], 'Ectocarpus, Polysiphonia and kelps have both multicellular phases.');
mc(3, 'life cycles', 'Fucus shows which life cycle?', 'Diplontic', ['Haplontic', 'Haplo-diplontic', 'None'], 'Fucus is diplontic.');
mc(3, 'life cycles', 'In algae with haplontic life cycle, meiosis occurs in', 'the zygote', ['the spore', 'the gamete', 'the vegetative cell'], 'Zygotic meiosis immediately restores the haploid.');
mc(3, 'life cycles', 'In diplontic plants the gametes are formed by', 'meiosis in the gamete mother cells', ['mitosis in a haploid body', 'fertilisation', 'binary fission'], 'The body is diploid, so meiosis precedes gametes.');

asr(2, 'algae', 'Algae are autotrophs.', 'Algae have chlorophyll for photosynthesis.', 0, 'Photosynthesis with chlorophyll makes them autotrophic.');
asr(3, 'algae', 'Red algae can live at great depths.', 'Phycoerythrin absorbs blue-green light that penetrates deep water.', 0, 'The pigment captures the light available at depth.');
asr(3, 'bryophytes', 'Bryophytes need water for fertilisation.', 'Their antherozoids are flagellated and must swim to the archegonium.', 0, 'Swimming gametes need a film of water.');
asr(3, 'pteridophytes', 'Selaginella is considered a step towards the seed habit.', 'Selaginella is homosporous.', 2, 'A is true. R is false: it is heterosporous.');
asr(4, 'gymnosperms', 'Conifers can survive in dry or cold conditions.', 'Their leaves are needle-like with a thick cuticle and sunken stomata.', 0, 'These features reduce water loss.');
asr(4, 'angiosperms', 'Angiosperm endosperm is triploid.', 'It forms by fusion of one male gamete with two polar nuclei.', 0, 'One haploid plus two haploid nuclei gives 3n.');
asr(4, 'life cycles', 'Bryophytes show alternation of generations.', 'The sporophyte and gametophyte are both multicellular in the life cycle.', 0, 'They alternate between a haploid gametophyte and a diploid sporophyte.');
asr(5, 'bryophytes', 'The sporophyte of a moss is dependent on the gametophyte.', 'The sporophyte is attached to the gametophyte and gets its nourishment from it.', 0, 'NCERT: the sporophyte is not free-living but attached to the photosynthetic gametophyte, from which it draws nourishment.');
asr(5, 'algae', 'Chlamydomonas is a unicellular alga.', 'Volvox is a colonial alga.', 1, 'Both are true, but one does not explain the other.', 'The two statements are separate facts.');
asr(5, 'gymnosperms', 'The pollen grain of a gymnosperm is a highly reduced male gametophyte.', 'It contains only a few cells.', 0, 'The reduced body of few cells is the reduction.');

stm(3, 'algae', 'Brown algae have laminarin and mannitol as reserve food.', 'Green algae store starch.', 0, 'Both are correct.');
stm(3, 'bryophytes', 'The dominant stage of mosses is the haploid gametophyte.', 'The sporophyte of mosses is free living.', 2, 'II is false.');
stm(3, 'pteridophytes', 'Pteridophytes have vascular tissue.', 'Pteridophytes produce seeds.', 2, 'They are seedless.');
stm(4, 'gymnosperms', 'Gymnosperms are heterosporous.', 'Gymnosperms produce flowers.', 2, 'II is false: they bear cones.');
stm(4, 'angiosperms', 'Double fertilisation is characteristic of angiosperms.', 'Triple fusion produces the zygote.', 2, 'Triple fusion produces the primary endosperm nucleus.');
stm(4, 'life cycles', 'Haplontic cycle: the dominant body is haploid.', 'Diplontic cycle: the dominant body is diploid.', 0, 'Both are correct.');
stm(4, 'algae', 'Phaeophyceae have pear-shaped zoospores with two unequal flagella.', 'Rhodophyceae have flagellated gametes.', 2, 'Red algae lack flagellated stages.');
mc(4, 'algae', 'Consider: (i) Spirogyra is filamentous. (ii) Volvox is colonial. (iii) Chlamydomonas is unicellular. (iv) Laminaria is unicellular. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(i), (ii), (iii) are correct. Laminaria is a large multicellular brown alga.', null, 'statements');
mc(4, 'pteridophytes', 'Consider: (i) Selaginella is heterosporous. (ii) Equisetum is a horsetail. (iii) Marchantia is a pteridophyte. (iv) Adiantum is a fern. How many are correct?', 'Three', ['Two', 'Four', 'One'], '(i), (ii), (iv) are correct. Marchantia is a liverwort.', null, 'statements');
mc(5, 'life cycles', 'Consider: (i) Bryophytes: dominant gametophyte. (ii) Pteridophytes: dominant sporophyte. (iii) Gymnosperms: dominant sporophyte. (iv) Angiosperms: dominant gametophyte. (v) Volvox: dominant diploid. How many are correct?', 'Three', ['Two', 'Four', 'Five'], '(i), (ii), (iii) are correct. Angiosperms have a dominant sporophyte and Volvox is haplontic.', null, 'statements');
mc(5, 'angiosperms', 'Consider: (i) The embryo sac is the female gametophyte. (ii) It has 8 nuclei but 7 cells. (iii) Synergids are at the chalazal end. (iv) Antipodals are three in number. (v) The egg apparatus is at the micropylar end. How many are correct?', 'Four', ['Three', 'Five', 'Two'], '(i), (ii), (iv), (v) are correct. Synergids are at the micropylar end, not the chalazal end.', 'Synergids are near the egg.', 'statements');
stm(5, 'algae', 'Carrageen is obtained from red algae.', 'Algin is obtained from green algae.', 2, 'II is false: algin comes from brown algae.');

// ---- Matches
match(2, 'plant groups', 'pkx1', 'Plant and group', ['A. Funaria', 'B. Dryopteris', 'C. Cycas', 'D. Spirogyra'], ['p. Bryophyte', 'q. Pteridophyte', 'r. Gymnosperm', 's. Alga'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-s, B-q, C-r, D-p'], 'Moss, fern, cycad and green alga.');
match(3, 'algae', 'pkx2', 'Algal group or genus and feature', ['A. Chlorophyceae', 'B. Phaeophyceae', 'C. Rhodophyceae', 'D. Volvox'], ['p. Starch and pyrenoids', 'q. Fucoxanthin and laminarin', 'r. Phycoerythrin and floridean starch', 's. Colonial and oogamous'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Each group has a distinctive pigment and reserve; Volvox is a colonial oogamous green alga.');
match(3, 'bryophytes', 'pkx3', 'Structure and plant', ['A. Gemma cup', 'B. Protonema', 'C. Peat', 'D. Archegonium'], ['p. Marchantia', 'q. Moss', 'r. Sphagnum', 's. Flask-shaped female sex organ'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'Gemma cups in Marchantia, protonema in moss, peat from Sphagnum, archegonium flask-shaped.');
match(3, 'pteridophytes', 'pkx4', 'Class and example', ['A. Psilopsida', 'B. Lycopsida', 'C. Sphenopsida', 'D. Pteropsida'], ['p. Equisetum', 'q. Psilotum', 'r. Selaginella', 's. Dryopteris'], 'A-q, B-r, C-p, D-s', ['A-r, B-q, C-p, D-s', 'A-q, B-r, C-s, D-p', 'A-p, B-r, C-q, D-s'], 'NCERT classes of pteridophytes.');
match(4, 'life cycles', 'pkx5', 'Plant and life cycle', ['A. Volvox', 'B. Fucus', 'C. Ectocarpus', 'D. Pinus'], ['p. Haplontic', 'q. Diplontic (alga)', 'r. Haplo-diplontic', 's. Diplontic (gymnosperm)'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Volvox: haplontic; Fucus: diplontic; Ectocarpus: haplo-diplontic; Pinus: diplontic.');
match(4, 'angiosperms', 'pkx6', 'Embryo sac part and number', ['A. Antipodals', 'B. Synergids', 'C. Polar nuclei', 'D. Egg cell'], ['p. 1', 'q. 2', 'r. 3', 's. 4'], 'A-r, B-q, C-q, D-p', ['A-r, B-q, C-p, D-q', 'A-q, B-r, C-q, D-p', 'A-r, B-p, C-q, D-q'], 'Three antipodals, two synergids, two polar nuclei, one egg. One entry of List II is used twice.', 'Two List I entries have the same answer.');
match(4, 'algae', 'pkx7', 'Algal product and use', ['A. Agar', 'B. Algin', 'C. Chlorella', 'D. Porphyra'], ['p. Gelidium and Gracilaria', 'q. Brown algae hydrocolloid', 'r. Single cell protein', 's. Edible red alga'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-p, B-r, C-q, D-s'], 'Standard NCERT facts.');
match(5, 'classification systems', 'pkx8', 'System and basis', ['A. Artificial', 'B. Natural', 'C. Phylogenetic', 'D. Numerical taxonomy'], ['p. Natural affinities of external and internal features', 'q. Evolutionary relationships', 'r. All characters coded and processed by computers', 's. A few vegetative and sexual characters'], 'A-s, B-p, C-q, D-r', ['A-r, B-p, C-q, D-s', 'A-s, B-p, C-r, D-q', 'A-q, B-p, C-s, D-r'], 'Artificial: few characters. Natural: natural affinities. Phylogenetic: evolutionary relationships. Numerical: coded characters analysed by computer.');
match(5, 'gymnosperms', 'pkx9', 'Gymnosperm and feature', ['A. Cycas', 'B. Pinus', 'C. Ginkgo', 'D. Sequoia'], ['p. Coralloid roots', 'q. Mycorrhiza and needle leaves', 'r. Maidenhair tree', 's. Giant redwood'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Common features of the genera.');
match(5, 'life cycles', 'pkx10', 'Plant and chromosome state (2n = 20 in the sporophyte)', ['A. Moss protonema cell', 'B. Fern prothallus cell', 'C. Pinus pollen grain nucleus', 'D. Angiosperm endosperm cell'], ['p. 10 (n)', 'q. 20 (2n)', 'r. 30 (3n)', 's. 40 (4n)'], 'A-p, B-p, C-p, D-r', ['A-p, B-q, C-p, D-r', 'A-q, B-p, C-p, D-r', 'A-p, B-p, C-q, D-s'], 'Protonema, prothallus and pollen are haploid (10). Endosperm of an angiosperm is triploid (30).', 'Three List I entries share one answer.');

// ---- Passages
pass('pkx11', 'Passage: a plant collected from a damp wall', 'A student finds a small green plant with a flat, ribbon-like body that lies on the ground. It is attached by unicellular rhizoids and has cup-like structures with small green buds on its upper surface. Later the same plant bears umbrella-shaped structures on stalks.');
pq('pkx11', 3, 'bryophytes', 'The plant is most probably', 'a liverwort such as Marchantia', ['a moss such as Funaria', 'a fern', 'a green alga'], 'A flat thallus with gemma cups points to Marchantia.');
pq('pkx11', 4, 'bryophytes', 'The small green buds in the cups are', 'gemmae, which are asexual', ['spores', 'eggs', 'zygotes'], 'Gemmae grow into new plants.');
pq('pkx11', 4, 'bryophytes', 'The plant body is', 'haploid', ['diploid', 'triploid', 'tetraploid'], 'The main plant body of a bryophyte is the haploid gametophyte.');
pass('pkx12', 'Passage: a seed plant', 'Plant S has pinnate leaves and a thick unbranched stem. Its roots include special ones growing upwards at the surface of the soil and associated with cyanobacteria. Its seeds are borne on leaf-like megasporophylls and are not enclosed in fruits.');
pq('pkx12', 3, 'gymnosperms', 'Plant S is', 'Cycas', ['Pinus', 'Mangifera', 'Equisetum'], 'Coralloid roots with cyanobacteria and pinnate leaves point to Cycas.');
pq('pkx12', 4, 'gymnosperms', 'The special roots are', 'coralloid roots', ['pneumatophores', 'prop roots', 'stilt roots'], 'They are associated with nitrogen-fixing cyanobacteria.');
pq('pkx12', 5, 'gymnosperms', 'A cell of the endosperm of its seed has n = 8. The zygote of this plant therefore has', '16 chromosomes', ['8 chromosomes', '24 chromosomes', '32 chromosomes'], 'Gymnosperm endosperm is haploid (female gametophyte, n = 8), so the zygote is 2n = 16.', 'In angiosperms endosperm is 3n.');
pass('pkx13', 'Passage: an embryo sac', 'A mature embryo sac of a flowering plant contains seven cells and eight nuclei. One male gamete of the pollen tube fuses with the egg and the other fuses with the central cell.');
pq('pkx13', 3, 'angiosperms', 'The fusion with the central cell produces', 'primary endosperm nucleus', ['zygote', 'embryo', 'seed coat'], 'The triple fusion forms the PEN.');
pq('pkx13', 4, 'angiosperms', 'If the plant has 2n = 24, the number of chromosomes in the primary endosperm nucleus is', '36', ['12', '24', '48'], 'n = 12; two polar nuclei (12 + 12) plus a male gamete (12) = 36.');
pq('pkx13', 5, 'angiosperms', 'The number of cells that do NOT take part in fertilisation in the embryo sac is', 'five (three antipodals and two synergids)', ['two', 'three', 'six'], 'Seven cells minus the egg and central cell is five.');

// ---- Level 4
mc(4, 'algae', 'Which statement about algae is NOT correct?', 'All algae are unicellular', ['Many are aquatic', 'They are autotrophic', 'They can reproduce by fragmentation'], 'Algae range from unicellular to large multicellular forms such as kelps.');
mc(4, 'algae', 'Which is NOT a characteristic of Phaeophyceae?', 'Phycoerythrin pigment', ['Fucoxanthin', 'Algin in the wall', 'Mannitol and laminarin'], 'Phycoerythrin is the red alga pigment.');
mc(4, 'algae', 'Which of the following has chlorophyll d?', 'Rhodophyceae', ['Chlorophyceae', 'Phaeophyceae', 'Bryophyta'], 'Red algae: chlorophyll a, d and phycoerythrin.');
mc(4, 'algae', 'Brown algae have chlorophyll', 'a and c', ['a and b', 'a and d', 'b and c'], 'They also have fucoxanthin.');
mc(4, 'algae', 'The vegetative reproduction of algae is generally by', 'fragmentation', ['zoospores', 'conidia', 'gemmae'], 'Each fragment grows into a thallus.');
mc(4, 'bryophytes', 'In bryophytes, meiosis takes place in', 'the spore mother cells of the capsule', ['the zygote', 'the antheridium', 'the archegonium'], 'The sporophyte forms haploid spores by meiosis.');
mc(4, 'bryophytes', 'Peat, which is used as fuel, is formed from', 'partially decomposed Sphagnum moss', ['marine brown algae', 'dried ferns', 'gymnosperm cones'], 'Sphagnum also holds much water, so it is used to pack and transport living plants.');
mc(4, 'pteridophytes', 'The gametophyte of pteridophytes is', 'independent and mostly photosynthetic', ['parasitic on sporophyte', 'a spore', 'diploid'], 'The prothallus is free-living.');
mc(4, 'pteridophytes', 'A feature which distinguishes pteridophytes from bryophytes is that pteridophytes', 'have vascular tissue and a dominant independent sporophyte', ['need water for fertilisation', 'have a thallus', 'produce spores'], 'Both need water for fertilisation and both produce spores.');
mc(4, 'gymnosperms', 'Gymnosperms differ from pteridophytes in having', 'seeds', ['xylem', 'spores', 'roots'], 'Gymnosperms are seed plants.');
mc(4, 'gymnosperms', 'Pollination in gymnosperms is mainly by', 'wind', ['insects', 'birds', 'water'], 'Pollen grains are carried by air currents.');
mc(4, 'gymnosperms', 'Which structure of Pinus carries the haploid female gametophyte?', 'Ovule', ['Microsporangium', 'Pollen tube', 'Needle'], 'The female gametophyte is within the ovule.');
mc(4, 'angiosperms', 'The number of nuclei in the egg apparatus of an angiosperm embryo sac is', 'Three', ['Two', 'Five', 'Eight'], 'One egg plus two synergids make three nuclei.', 'Eight is the total for the whole embryo sac.');
mc(4, 'angiosperms', 'Pollen grains of angiosperms are formed in', 'anthers', ['ovaries', 'stigma', 'style'], 'Anthers contain microsporangia.');
mc(4, 'angiosperms', 'Dicots have', 'two cotyledons', ['one cotyledon', 'no cotyledons', 'three cotyledons'], 'Monocots have one cotyledon.');
mc(4, 'life cycles', 'In plants with a diplontic life cycle, the only haploid stage is', 'the gametes', ['the zygote', 'the plant body', 'the spore mother cell'], 'The body and zygote are diploid.');
mc(4, 'life cycles', 'In a haplontic life cycle, the only diploid stage is', 'the zygote', ['the gamete', 'the vegetative body', 'the spore'], 'The zygote divides meiotically to give haploid.');
mc(4, 'life cycles', 'Which one shows sporic meiosis?', 'A fern', ['Volvox', 'Spirogyra', 'Chlamydomonas'], 'Meiosis in spore mother cells.');
mc(4, 'classification systems', 'Which of the following uses the arrangement of the androecium?', 'The artificial system', ['The natural system', 'The phylogenetic system', 'Chemotaxonomy'], 'Linnaeus classed plants by stamen number and arrangement.');
mc(4, 'algae', 'Which statement is true for Chlorophyceae?', 'Chlorophyll a and b with pyrenoids', ['Fucoxanthin with laminarin', 'Phycoerythrin with floridean starch', 'Algin in the cell wall'], 'These are the chlorophyte features.');

// ---- Level 5
mc(5, 'algae', 'The two pigments listed for Rhodophyceae and Phaeophyceae besides chlorophyll a are', 'phycoerythrin and fucoxanthin respectively', ['fucoxanthin and phycoerythrin respectively', 'chlorophyll b for both', 'carotene for both'], 'Red algae: r-phycoerythrin. Brown algae: fucoxanthin.', 'The order of the two names is easily reversed.');
mc(5, 'bryophytes', 'Which of these shows haplo-diplontic life with the dominant haploid body?', 'Moss', ['Fern', 'Pinus', 'Mango'], 'Dominant gametophyte in bryophytes.');
mc(5, 'pteridophytes', 'How many of the following are seedless vascular plants: Funaria, Selaginella, Pinus, Equisetum?', 'Two', ['One', 'Three', 'Four'], 'Selaginella and Equisetum. Funaria is a bryophyte and Pinus is a seed plant.');
mc(5, 'gymnosperms', 'Which statement about the pollen grain of Pinus is correct?', 'It is haploid and is the male gametophyte', ['It is diploid and a sporophyte', 'It is a megaspore', 'It is formed by mitosis from the zygote'], 'Microspore mother cells divide by meiosis to give haploid microspores that develop into pollen grains.');
mc(5, 'angiosperms', 'Which statement is true for triple fusion?', 'It fuses the male gamete with the two polar nuclei', ['It fuses the male gamete with the egg', 'It fuses two male gametes', 'It forms the zygote'], 'Triple fusion forms the primary endosperm nucleus.', 'Syngamy forms the zygote.');
mc(5, 'angiosperms', 'A plant with 2n = 28 has how many chromosomes in the antipodal cell?', '14', ['28', '42', '7'], 'The embryo sac cells are haploid: n = 14.');
mc(5, 'life cycles', 'In a plant with 2n = 22, how many chromosomes are present in a spore mother cell, a spore and a zygote respectively?', '22, 11, 22', ['11, 11, 22', '22, 22, 11', '11, 22, 11'], 'Spore mother cell is diploid, spores are haploid, zygote diploid.');
mc(5, 'life cycles', 'A bryophyte gametophyte cell has 18 chromosomes. How many chromosomes are present in a cell of the capsule wall?', '36', ['18', '9', '72'], 'The capsule wall belongs to the sporophyte (2n = 36).');
mc(5, 'classification systems', 'Which approach would best show that two look-alike plants are different species with different chromosome counts?', 'Cytotaxonomy', ['Chemotaxonomy', 'Artificial system', 'Herbarium alone'], 'Chromosome number and behaviour are cytological.');
export default { topic: 'plant-kingdom', groups, items, gens: [] };
